package com.riskguard.transaction.config;
import io.swagger.v3.oas.models.Components; import io.swagger.v3.oas.models.OpenAPI; import io.swagger.v3.oas.models.info.Contact; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.security.SecurityRequirement; import io.swagger.v3.oas.models.security.SecurityScheme; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
@Configuration public class OpenApiConfiguration { @Bean OpenAPI riskGuardOpenAPI(){String scheme="bearerAuth";return new OpenAPI().info(new Info().title("RiskGuard Transaction API").description("API educacional de transações, clientes, risco, reviews e dashboard. Não processa dinheiro real.").version("v1").contact(new Contact().name("RiskGuard"))).components(new Components().addSecuritySchemes(scheme,new SecurityScheme().name(scheme).type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList(scheme));} }
